<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue';import Icon from './Icon.vue';import P6Dialog from './P6Dialog.vue';import {money,decimal} from './tradeAmounts';import {cents} from './commerceAmounts';import './p6.css';
type Row=Record<string,any>;
const props=defineProps<{section:string;request:<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;download:(path:string,name:string)=>Promise<void>;memberId:string;username:string;readonly:boolean}>();const emit=defineEmits<{navigate:[view:string]}>();
const busy=ref(false),error=ref(''),success=ref(''),data=ref<Row>({}),catalog=ref<Row>({objects:[],plan:{}}),rows=ref<Row[]>([]),total=ref(0),page=ref(1),query=ref(''),year=ref(new Date().getFullYear()),type=ref('ORDER'),dialog=ref(''),editor=ref<Row>({}),fields=ref<Row[]>([]),values=reactive<Row>({}),versions=ref<Row>({}),attachments=ref<Row[]>([]),upload=ref<File|null>(null),batch=ref<Row|null>(null),csv=ref<File|null>(null),templates=ref<Row[]>([]),oneTime=ref(''),notes=ref(''),members=ref<Row[]>([]),targetRecords=ref<Row[]>([]),targetQuery=ref(''),targetPage=ref(1),targetTotal=ref(0),history=ref<Row[]>([]),tab=ref('rules');
const names:Record<string,string>={CUSTOMER:'客户',CONTACT:'联系人',LEAD:'线索',OPPORTUNITY:'商机',QUOTE:'报价',ORDER:'销售订单',CONTRACT:'合同',RECEIPT:'回款',TICKET:'服务工单',INVOICE:'开票申请',EXPENSE:'支出',TARGET:'业绩目标',COMMISSION:'提成核算',WEEKLY:'销售周报',PRODUCT:'产品',FUND:'资金账户'};
const originalViews:Record<string,string>={CUSTOMER:'customers',LEAD:'leads',OPPORTUNITY:'opportunities',QUOTE:'quotes',ORDER:'sales-orders',CONTRACT:'contracts',RECEIPT:'receipts',TICKET:'tickets',INVOICE:'invoices',EXPENSE:'expenses',TARGET:'targets',COMMISSION:'commissions',WEEKLY:'weeklies',PRODUCT:'products'};
const statuses:Record<string,string>={DRAFT:'草稿',ACTIVE:'已启用',PAUSED:'已停用',PENDING:'等待执行',RETRY:'待重试',SUCCESS:'成功',SKIPPED:'条件未满足',BLOCKED:'授权或版本已变化',DEAD:'失败终止',PREVIEW:'待核对',COMMITTED:'已入库',SUBMITTED:'待审批',APPROVED:'已批准',CONFIRMED:'已确认',IN_DELIVERY:'交付中',DELIVERED:'已交付',ISSUED:'已登记发票',VOID:'已作废',LOCKED:'已锁定',REVIEWED:'已复核',NEW:'新建',IN_PROGRESS:'处理中',WAITING_CUSTOMER:'等待客户',RESOLVED:'已解决',CLOSED:'已关闭',PASS:'已就绪',TODO:'待完成',SIGNED:'已签订',TERMINATED:'已终止',REVERSED:'已冲销',REJECTED:'已退回',CONTACTED:'已联系',QUALIFIED:'合格',UNQUALIFIED:'不合格',CONVERTED:'已转客户',CANCELLED:'已取消',INACTIVE:'未启用',CONTACT:'初次接触',NEEDS:'需求确认',SOLUTION:'方案讨论',NEGOTIATION:'报价谈判',READY:'签约准备',WON:'成交',LOST:'丢单',CONDITION:'条件触发',SCHEDULE:'每日定时',MANUAL:'手动触发'};
const titles:Record<string,string>={automation:'自动化规则','object-workspace':'业务扩展工作台',migration:'数据迁移',pilot:'试点检查','object-policies':'新增对象权限','public-forms':'外链表单','business-notices':'业务通知'};
const actions:Record<string,string>={FILL_CUSTOMER_LEVEL:'填充客户等级',CREATE_TASK:'生成跟进待办',NOTIFY:'发送站内提醒',ASSIGN:'分配客户或线索',RETURN_POOL:'回收到资源池',SUBMIT_QUOTE:'发起报价审批',CREATE_ORDER:'从批准报价生成订单'};
const availableActions=computed(()=>Object.fromEntries(Object.entries(actions).filter(([id])=>['NOTIFY','CREATE_TASK'].includes(id)||['ASSIGN','RETURN_POOL','FILL_CUSTOMER_LEVEL'].includes(id)&&['CUSTOMER','LEAD'].includes(editor.value.entityType)&&(id!=='FILL_CUSTOMER_LEVEL'||editor.value.entityType==='CUSTOMER')||['SUBMIT_QUOTE','CREATE_ORDER'].includes(id)&&editor.value.entityType==='QUOTE')));
const conditionFields:Record<string,string>={status:'状态',stage:'商机阶段',level:'客户等级',industry:'行业',region:'地区',amountCents:'金额（元）',inactiveDays:'距上次更新天数'};
const roleNames:Record<string,string>={TENANT_ADMIN:'企业管理',SALES_MANAGER:'销售经理',SALES:'销售',VIEWER:'只读成员'};
const stages:Record<string,string>={CONTACT:'初次接触',NEEDS:'需求确认',SOLUTION:'方案讨论',NEGOTIATION:'报价谈判',READY:'签约准备',WON:'成交',LOST:'丢单'};
const stateOptions=computed(()=>({CUSTOMER:[],LEAD:['NEW','CONTACTED','QUALIFIED','UNQUALIFIED','CONVERTED'],QUOTE:['DRAFT','SUBMITTED','APPROVED','REJECTED','VOID'],ORDER:['DRAFT','CONFIRMED','IN_DELIVERY','DELIVERED','VOID'],CONTRACT:['DRAFT','SIGNED','ACTIVE','TERMINATED','VOID'],RECEIPT:['DRAFT','CONFIRMED','REVERSED','VOID'],INVOICE:['DRAFT','SUBMITTED','APPROVED','ISSUED','VOID'],EXPENSE:['DRAFT','CONFIRMED','REVERSED','VOID'],COMMISSION:['DRAFT','REVIEWED','LOCKED'],WEEKLY:['DRAFT','SUBMITTED','APPROVED'],TICKET:['NEW','IN_PROGRESS','WAITING_CUSTOMER','RESOLVED','CLOSED','CANCELLED'],PRODUCT:['ACTIVE','INACTIVE']} as Record<string,string[]>)[editor.value.entityType]??[]);
const availableConditionFields=computed(()=>Object.fromEntries(Object.entries(conditionFields).filter(([key])=>key==='status'?stateOptions.value.length>0:key==='stage'?editor.value.entityType==='OPPORTUNITY':key==='level'?editor.value.entityType==='CUSTOMER':['industry','region'].includes(key)?['CUSTOMER','LEAD'].includes(editor.value.entityType):key==='amountCents'?!['CUSTOMER','LEAD','TICKET'].includes(editor.value.entityType):true)));
const currentTemplate=computed(()=>templates.value.find(t=>t.id===type.value));const pendingErrors=computed(()=>batch.value?.rowsData?.some((r:Row)=>r.errors.length));const objects=computed<Row[]>(()=>catalog.value.objects??[]);const currentObject=computed(()=>objects.value.find(x=>x.id===type.value));
const uiDate=(v:any)=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';const label=(v:any)=>statuses[String(v)]??v??'—';const key=()=>({'Idempotency-Key':crypto.randomUUID()});
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){error.value=(e as Error).message;if([401,403,404].includes((e as Error&{status:number}).status)){rows.value=[];batch.value=null;dialog.value='';}}finally{busy.value=false;}}
async function load(){if(props.section==='automation'){data.value=await props.request<Row>('/automation');members.value=data.value.members;const list=await props.request<Row>('/automation/runs?page='+page.value);rows.value=list.items;total.value=list.total;}
 else if(props.section==='object-workspace'){catalog.value=await props.request<Row>('/workspace/catalog');templates.value=(await props.request<Row>('/workspace/draft-templates')).items;if(!objects.value.some(o=>o.id===type.value))type.value=objects.value[0]?.id??'ORDER';if(objects.value.length){const p=await props.request<Row>(`/workspace/objects/${type.value}?page=${page.value}&pageSize=20&q=${encodeURIComponent(query.value)}&year=${year.value}`);rows.value=p.items;total.value=p.total;}}
 else if(props.section==='migration'){const t=await props.request<Row>('/migrations/templates');templates.value=t.items;data.value=t;if(!templates.value.some(o=>o.id===type.value))type.value=templates.value[0]?.id??'LEAD';rows.value=(await props.request<Row>('/migrations')).items;}
 else if(props.section==='pilot'){data.value=await props.request<Row>('/pilot/readiness');history.value=(await props.request<Row>('/pilot/history')).items;}
 else if(props.section==='object-policies'){data.value=await props.request<Row>('/workspace/object-policies');rows.value=data.value.items;}
 else if(props.section==='public-forms'){data.value=await props.request<Row>('/workspace/public-forms');rows.value=data.value.items;members.value=(await props.request<Row>('/automation')).members;}
 else if(props.section==='business-notices'){data.value=await props.request<Row>('/workspace/notices');rows.value=data.value.items;}}
function switchType(){page.value=1;query.value='';batch.value=null;run(load);}
function editRule(row?:Row){editor.value=row?JSON.parse(JSON.stringify(row)):{name:'',entityType:'CUSTOMER',triggerType:'MANUAL',ownerMemberId:props.memberId,expectedVersion:0,definition:{conditions:[],actions:[{type:'NOTIFY',value:'需要跟进客户',memberId:props.memberId,dueDays:0}],scheduleHour:9}};editor.value.expectedVersion=row?.version??0;for(const c of editor.value.definition.conditions)if(c.field==='amountCents')c.value=decimal(c.value);dialog.value='rule';}
async function saveRule(){const payload=JSON.parse(JSON.stringify(editor.value));for(const c of payload.definition.conditions)if(c.field==='amountCents')c.value=String(cents(c.value));await props.request('/automation/rules'+(editor.value.id?'/'+editor.value.id:''),editor.value.id?'PUT':'POST',payload,key());dialog.value='';await load();success.value='规则已保存为草稿，请核对并发布。';}
async function ruleState(row:Row,action:string){await props.request(`/automation/rules/${row.id}/${action}`,'POST',{expectedVersion:row.version});await load();success.value=action==='publish'?'规则已发布。':'规则已停用，未执行任务会重新核验状态。';}
async function loadTargets(){const row=editor.value.rule;const p=await props.request<Row>(`/workspace/objects/${row.entityType}?page=${targetPage.value}&pageSize=20&q=${encodeURIComponent(targetQuery.value)}&year=${year.value}`);targetRecords.value=p.items;targetTotal.value=p.total;}
async function executeOpen(row:Row){editor.value={rule:row,recordId:''};targetQuery.value='';targetPage.value=1;await loadTargets();dialog.value='execute';}
async function execute(){const result=await props.request<Row>(`/automation/rules/${editor.value.rule.id}/execute`,'POST',{recordId:editor.value.recordId,expectedVersion:editor.value.rule.version},key());dialog.value='';await load();success.value='执行结果：'+label(result.status);}
async function runDetails(row:Row){editor.value=await props.request<Row>('/automation/runs/'+row.id);dialog.value='run';}
async function retry(row:Row){await props.request('/automation/runs/'+row.id+'/retry','POST');await load();success.value='已重新执行，请查看结果。';}
async function revisions(row:Row){editor.value={rule:row,...await props.request<Row>('/automation/rules/'+row.id+'/revisions')};dialog.value='revisions';}
async function openRecord(row:Row){const [ext,files]=await Promise.all([props.request<Row>(`/workspace/objects/${type.value}/${row.id}/fields`),props.request<Row>(`/workspace/objects/${type.value}/${row.id}/attachments`).catch((e:Error&{status?:number})=>{if(e.status===403)return{items:[],storageConfigured:false};throw e;})]);editor.value=ext.record;fields.value=ext.fields;attachments.value=files.items;data.value.storageConfigured=files.storageConfigured;for(const k of Object.keys(values))delete values[k];versions.value={};for(const field of ext.fields)values[field.id]=field.dataType==='BOOLEAN'?false:field.dataType==='MULTI_SELECT'?[]:'';for(const item of ext.values){values[item.fieldId]=item.value;versions.value[item.fieldId]=item.version;}upload.value=null;dialog.value='record';}
async function saveFields(){const allowed=Object.fromEntries(fields.value.filter(f=>f.canWrite).map(f=>[f.id,values[f.id]]));await props.request(`/workspace/objects/${type.value}/${editor.value.id}/fields`,'PUT',{values:allowed,versions:versions.value,expectedRecordVersion:editor.value.version});await openRecord(editor.value);success.value='扩展资料已保存。';}
async function uploadFile(){if(!upload.value)return;const f=new FormData();f.append('file',upload.value);await props.request(`/workspace/objects/${type.value}/${editor.value.id}/attachments`,'POST',f,key());await openRecord(editor.value);success.value='附件已上传。';}
async function removeFile(file:Row){await props.request(`/workspace/attachments/${file.id}?expectedVersion=${file.version}`,'DELETE');await openRecord(editor.value);}
function createDraft(){editor.value={};for(const name of currentTemplate.value?.columns??[])editor.value[name]='';if(type.value==='PRODUCT')Object.assign(editor.value,{'类别':'产品','单位':'件','成本（元）':'0','税率（%）':'13'});if(type.value==='TARGET')Object.assign(editor.value,{'目标对象':props.username,'月份':new Date().toISOString().slice(0,7),'周期月数':'1'});dialog.value='draft';}
async function saveDraft(){await props.request(`/workspace/objects/${type.value}`,'POST',{values:editor.value},key());dialog.value='';await load();success.value='已生成业务记录；审批、确认与履约继续在原业务模块完成。';}
async function preview(){if(!csv.value)throw new Error('请先选择CSV文件');if(csv.value.size>524288)throw new Error('CSV文件最多512KB');const bytes=new Uint8Array(await csv.value.arrayBuffer());let encoded='';for(let offset=0;offset<bytes.length;offset+=8192)encoded+=String.fromCharCode(...bytes.subarray(offset,offset+8192));batch.value=await props.request<Row>('/migrations/preview','POST',{entityType:type.value,fileName:csv.value.name,csvBase64:btoa(encoded)},key());await load();}
async function openBatch(row:Row){batch.value=await props.request<Row>('/migrations/'+row.id);type.value=batch.value!.entityType;}
async function commit(){if(!batch.value)return;batch.value=await props.request<Row>(`/migrations/${batch.value.id}/commit`,'POST',{expectedVersion:batch.value.version},key());await load();success.value='该批次已整批入库，重复提交不会生成重复业务。';}
function policyOpen(row?:Row){editor.value=row?JSON.parse(JSON.stringify(row)):{entityType:'ORDER',roleCode:'SALES',canRead:true,canWrite:true,expectedVersion:0};editor.value.expectedVersion=row?.version??0;dialog.value='policy';}
async function savePolicy(){await props.request('/workspace/object-policies/'+editor.value.entityType,'PUT',editor.value);dialog.value='';await load();success.value='对象权限已更新；原有记录范围继续生效。';}
function formOpen(){editor.value={name:'',entityType:'LEAD',ownerMemberId:props.memberId,expiresDays:30};dialog.value='form';}
async function createForm(){const response=await props.request<Row>('/workspace/public-forms','POST',editor.value);oneTime.value=window.location.origin+response.path;dialog.value='link';await load();}
async function revokeForm(row:Row){await props.request('/workspace/public-forms/'+row.id+'?expectedVersion='+row.version,'DELETE');await load();}
async function savePilot(){await props.request('/pilot/checks','POST',{notes:notes.value});notes.value='';await load();success.value='试点核验记录已归档。';}
function turn(delta:number){page.value+=delta;run(load);}
function inputType(name:string){return name==='月份'?'month':/日期|周起始日/.test(name)?'date':/金额|售价|成本|税率|周期月数/.test(name)?'number':'text';}
watch(()=>props.section,()=>{page.value=1;query.value='';dialog.value='';batch.value=null;rows.value=[];data.value={};run(load);},{immediate:true});
</script>
<template>
<section class="p6 p7-workspace" :aria-busy="busy"><div class="page-heading"><div><span class="eyebrow">BUSINESS OPERATIONS</span><h1>{{titles[section]}}</h1><p>{{section==='automation'?'通过受控规则减少重复操作，保留版本、授权与执行历史。':section==='object-workspace'?'在授权范围内搜索业务记录、维护扩展资料并保管附件。':section==='migration'?'下载模板、预校验，再整批入库；提交失败时整批回滚。':section==='pilot'?'逐项核对试点准备与业务演练情况，归档本次检查。':section==='public-forms'?'使用限时外链收集线索或客户服务需求，提交后进入原业务流程。':section==='object-policies'?'为新增对象配置读取与写入权限，原业务记录范围继续生效。':'查看与你相关且当前仍可读取的业务提醒。'}}</p></div><button class="btn secondary" :disabled="busy" @click="run(load)"><Icon name="refresh" :size="16"/>刷新</button></div><p v-if="error" class="p6-error" role="alert">{{error}}</p><p v-if="success" class="p6-success" role="status">{{success}}</p><p v-if="busy" class="p6-muted" role="status">正在处理…</p>
<template v-if="section==='automation'"><div class="p6-toolbar"><button class="btn primary" :disabled="busy||readonly" @click="editRule()">新建规则</button><button class="btn secondary" :disabled="busy||readonly" @click="run(async()=>{await request('/automation/run-due','POST');await load();success='已检查待触发规则与待执行任务。';})">执行到期检查</button><span class="p6-muted">后台定时调度：{{data.schedulerEnabled?'已开启':'尚未开启，可手动检查'}} · 规则上限 {{data.plan?.automationRuleLimit??'—'}} 条</span></div><div class="p6-tabs"><button class="btn secondary" :class="{active:tab==='rules'}" @click="tab='rules'">规则配置</button><button class="btn secondary" :class="{active:tab==='runs'}" @click="tab='runs'">执行记录</button></div><section class="p6-card"><div class="p7-scroll"><table v-if="tab==='rules'"><thead><tr><th>规则名称</th><th>对象 / 触发方式</th><th>状态 / 版本</th><th>操作</th></tr></thead><tbody><tr v-for="row in data.items??[]" :key="row.id"><td>{{row.name}}</td><td>{{names[row.entityType]}}<small>{{label(row.triggerType)}}</small></td><td>{{label(row.status)}}<small>版本 {{row.version}}</small></td><td><div class="p6-actions"><button class="text-button" :disabled="busy||readonly" @click="editRule(row)">编辑</button><button v-if="row.status!=='ACTIVE'" class="text-button" :disabled="busy||readonly" @click="run(()=>ruleState(row,'publish'))">发布</button><button v-else class="text-button" :disabled="busy||readonly" @click="run(()=>ruleState(row,'pause'))">停用</button><button v-if="row.status==='ACTIVE'" class="text-button" :disabled="busy||readonly" @click="run(()=>executeOpen(row))">手动执行</button><button class="text-button" :disabled="busy" @click="run(()=>revisions(row))">发布历史</button></div></td></tr><tr v-if="!data.items?.length"><td colspan="4">还没有规则，点击“新建规则”开始配置。</td></tr></tbody></table><table v-else><thead><tr><th>规则 / 版本</th><th>执行状态</th><th>尝试次数</th><th>开始时间</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.ruleName}}<small>版本 {{row.ruleVersion}}</small></td><td>{{label(row.status)}}<small>{{row.errorCode?'请查看详情并核对规则、状态与授权':''}}</small></td><td>{{row.attempts}} / 5</td><td>{{uiDate(row.createdAt)}}</td><td><button class="text-button" :disabled="busy" @click="run(()=>runDetails(row))">详情</button><button v-if="['BLOCKED','DEAD','RETRY'].includes(row.status)&&row.attempts<5" class="text-button" :disabled="busy||readonly" @click="run(()=>retry(row))">重试</button></td></tr><tr v-if="!rows.length"><td colspan="5">暂无执行记录</td></tr></tbody></table></div><div v-if="tab==='runs'" class="p6-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></section><p class="p6-muted">保存修改会转为草稿，发布后才生效。旧版本、已停用规则及授权发生变化的任务会停止；规则不能自动批准报价、确认回款或锁定提成。</p></template>
<template v-else-if="section==='object-workspace'"><div class="p6-toolbar"><button class="btn secondary" @click="emit('navigate',originalViews[type]!)">前往原业务模块</button><span class="p6-muted">审批、履约及到账确认可在对应业务模块继续办理。</span></div><form class="p6-toolbar" @submit.prevent="page=1;run(load)"><label>业务对象<select v-model="type" aria-label="业务对象" :disabled="busy" @change="switchType"><option v-for="o in objects" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>搜索<input v-model="query" maxlength="100" placeholder="业务名称、编号或客户"/></label><label v-if="['TARGET','COMMISSION','WEEKLY'].includes(type)">归属年份<input v-model.number="year" type="number" min="2000" max="2100"/></label><button class="btn primary" :disabled="busy">搜索</button><button v-if="currentObject?.canWrite&&currentTemplate" type="button" class="btn secondary" :disabled="busy||readonly" @click="createDraft">快捷新增</button><button type="button" class="btn secondary" :disabled="busy||!rows.length" @click="run(()=>download(`/workspace/objects/${type}/export?year=${year}&q=${encodeURIComponent(query)}`,`${names[type]}清单.csv`))">导出清单</button></form><section class="p6-card"><div class="p7-scroll"><table><thead><tr><th>业务名称</th><th>客户 / 负责人</th><th>状态</th><th>金额</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td class="p7-title-cell">{{row.recordTitle}}</td><td>{{row.customerName??'—'}}<small>{{row.ownerName??row.memberName??'—'}}</small></td><td>{{label(row.status??row.stage)}}</td><td>{{money(row.totalCents??row.amountCents??row.targetCents??row.commissionCents??row.priceCents)}}</td><td><button class="text-button" :disabled="busy" @click="run(()=>openRecord(row))">资料与附件</button></td></tr><tr v-if="!rows.length"><td colspan="5">当前范围暂无可见业务记录</td></tr></tbody></table></div><div class="p6-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></section></template>
<template v-else-if="section==='migration'"><section class="p6-card"><h2>准备迁移文件</h2><form class="p6-toolbar" @submit.prevent="run(preview)"><label>模板类型<select v-model="type" aria-label="模板类型" :disabled="busy" @change="batch=null"><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><button type="button" class="btn secondary" :disabled="busy" @click="run(()=>download('/migrations/templates/'+type,`${names[type]}迁移模板.csv`))">下载模板</button><label>CSV文件<input type="file" accept=".csv,text/csv" @change="csv=($event.target as HTMLInputElement).files?.[0]??null"/></label><button class="btn primary" :disabled="busy||readonly||!csv">预校验</button></form><p class="p6-muted">每批最多200行、512KB，使用UTF-8编码。客户导入可从左侧“导入导出”进入。确认到账、审批、提成计算及锁定继续走原业务流程。</p></section><section v-if="batch" class="p6-card"><div class="p7-row"><div><h2>{{batch.fileName}}</h2><p class="p6-muted">{{label(batch.status)}} · 共 {{batch.rowsData?.length??0}} 行</p></div><button v-if="batch.status==='PREVIEW'" class="btn primary" :disabled="busy||readonly||pendingErrors" @click="run(commit)">核对后整批入库</button><button v-if="pendingErrors" class="btn secondary" :disabled="busy" @click="run(()=>download(`/migrations/${batch!.id}/errors`,'迁移错误清单.csv'))">下载错误清单</button></div><div class="p7-scroll"><table><thead><tr><th>行号</th><th>资料预览</th><th>校验结果</th></tr></thead><tbody><tr v-for="item in batch.rowsData??[]" :key="item.number"><td>{{item.number}}</td><td class="p7-title-cell">{{Object.entries(item.values).map(([k,v])=>`${k}：${v}`).join('；')}}</td><td :class="{'p7-bad':item.errors.length}">{{item.errors.length?item.errors.join('；'):'通过'}}</td></tr></tbody></table></div><p v-if="batch.status==='COMMITTED'" class="p6-success">已创建 {{batch.results?.length??0}} 条业务记录，可到业务扩展工作台或原业务模块查看。</p></section><section class="p6-card"><h2>迁移批次</h2><div class="p7-scroll"><table><thead><tr><th>文件</th><th>对象</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.fileName}}</td><td>{{names[row.entityType]}}</td><td>{{label(row.status)}}</td><td>{{uiDate(row.createdAt)}}</td><td><button class="text-button" :disabled="busy" @click="run(()=>openBatch(row))">查看</button></td></tr><tr v-if="!rows.length"><td colspan="5">暂无迁移批次</td></tr></tbody></table></div></section></template>
<template v-else-if="section==='pilot'"><div class="p6-kpis"><article><span>已就绪</span><strong>{{data.passed??0}} / {{data.total??0}}</strong><small>系统检查与业务演练准备</small></article></div><section class="p6-card"><div v-for="check in data.checks??[]" :key="check.code" class="p7-check"><span :class="['p7-status',check.status==='PASS'?'p7-pass':'p7-todo']">{{label(check.status)}}</span><div><strong>{{check.name}}</strong><p class="p6-muted">{{check.detail}}</p></div><button v-if="check.view" class="btn secondary" @click="emit('navigate',check.view)">前往处理</button></div></section><section class="p6-card"><h2>归档本次核验</h2><p class="p6-muted">正式邮件投递和客户实际试用需由试点参与方完成核验，系统检查结果不会替代客户签收。</p><form @submit.prevent="run(savePilot)"><label>核验说明<textarea v-model="notes" required maxlength="2000" rows="3" placeholder="记录本次演练情况、待办及试点负责人"/></label><button class="btn primary" :disabled="busy||readonly">归档检查记录</button></form><div v-for="row in history" :key="row.id" class="p6-record"><strong>{{uiDate(row.createdAt)}}</strong><p class="p6-copy">{{row.notes}}</p></div></section></template>
<template v-else-if="section==='object-policies'"><div class="p6-toolbar"><button class="btn primary" :disabled="busy||readonly" @click="policyOpen()">配置对象权限</button><p class="p6-muted">仅能限制原业务授权，不能扩大客户、部门或单据的记录范围。</p></div><section class="p6-card p7-scroll"><table><thead><tr><th>业务对象</th><th>角色</th><th>读取</th><th>写入</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.entityType+row.roleCode"><td>{{names[row.entityType]}}</td><td>{{roleNames[row.roleCode]}}</td><td>{{row.canRead?'允许':'不允许'}}</td><td>{{row.canWrite?'允许':'不允许'}}</td><td><button class="text-button" :disabled="busy||readonly" @click="policyOpen(row)">编辑</button></td></tr><tr v-if="!rows.length"><td colspan="5">尚未设置额外限制，沿用原角色与记录权限。</td></tr></tbody></table></section></template>
<template v-else-if="section==='public-forms'"><div class="p6-toolbar"><button class="btn primary" :disabled="busy||readonly" @click="formOpen">新建外链表单</button><span class="p6-muted">有效表单上限 {{data.plan?.publicFormLimit??'—'}} 个 · 本月提交上限 {{data.plan?.publicSubmissionMonthlyLimit??'—'}} 次</span></div><section class="p6-card p7-scroll"><table><thead><tr><th>名称</th><th>业务类型</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.name}}</td><td>{{names[row.entityType]}}</td><td>{{uiDate(row.expiresAt)}}</td><td>{{row.active?'有效':'已撤销'}}</td><td><button v-if="row.active" class="text-button" :disabled="busy||readonly" @click="run(()=>revokeForm(row))">撤销链接</button></td></tr><tr v-if="!rows.length"><td colspan="5">暂无外链表单</td></tr></tbody></table></section><p class="p6-muted">外链仅收集固定业务资料，提交需联系授权。链接、归属成员授权、套餐和频率均会重新校验。</p></template>
<template v-else-if="section==='business-notices'"><section class="p6-card"><p v-if="!rows.length" class="p6-muted">暂无可见业务提醒</p><article v-for="row in rows" :key="row.id" class="p7-check"><div><strong>{{row.title}}</strong><p>{{names[row.entityType]}} · {{row.recordTitle}}</p><small>{{uiDate(row.createdAt)}} · {{row.readAt?'已读':'未读'}}</small></div><button v-if="!row.readAt" class="btn secondary" :disabled="busy" @click="run(async()=>{await request('/workspace/notices/'+row.id+'/read','POST');await load();})">标为已读</button></article></section></template>
<P6Dialog v-if="dialog" :title="dialog==='rule'?'配置自动化规则':dialog==='execute'?'手动执行规则':dialog==='record'?'业务资料与附件':dialog==='draft'?'快捷新增'+names[type]:dialog==='policy'?'配置对象权限':dialog==='form'?'新建外链表单':dialog==='link'?'复制外链表单链接':dialog==='run'?'自动化执行详情':'规则发布历史'" :busy="busy" @close="!busy&&(dialog='')"><p v-if="error" class="p6-error" role="alert">{{error}}</p><p v-if="success" class="p6-success">{{success}}</p>
<form v-if="dialog==='rule'" @submit.prevent="run(saveRule)"><fieldset :disabled="busy||readonly"><div class="p6-grid"><label>规则名称<input v-model="editor.name" required maxlength="100"/></label><label>业务对象<select v-model="editor.entityType" @change="editor.definition.conditions=[];editor.definition.actions=[{type:'NOTIFY',value:'',memberId:null,dueDays:0}]"><option v-for="(name,id) in data.objects" :key="id" :value="id">{{name}}</option></select></label><label>触发方式<select v-model="editor.triggerType"><option value="MANUAL">手动触发</option><option value="CONDITION">业务创建或更新时</option><option value="SCHEDULE">每日定时</option></select></label><label>执行成员<select v-model="editor.ownerMemberId" required><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label v-if="editor.triggerType==='SCHEDULE'">上海时间每日几点开始<input v-model.number="editor.definition.scheduleHour" type="number" min="0" max="23"/></label></div><h3>全部满足以下条件时执行</h3><div v-for="(condition,index) in editor.definition.conditions" :key="index" class="p7-form-row"><label>字段<select v-model="condition.field"><option v-for="(name,key) in availableConditionFields" :key="key" :value="key">{{name}}</option></select></label><label>比较<select v-model="condition.operator"><option value="EQ">等于</option><option value="NE">不等于</option><option value="GTE">大于等于</option><option value="LTE">小于等于</option></select></label><label>条件值<select v-if="condition.field==='status'" v-model="condition.value" required><option value="" disabled>请选择业务状态</option><option v-for="state in stateOptions" :key="state" :value="state">{{label(state)}}</option></select><select v-else-if="condition.field==='stage'" v-model="condition.value" required><option v-for="(name,id) in stages" :key="id" :value="id">{{name}}</option></select><select v-else-if="condition.field==='level'" v-model="condition.value" required><option>A</option><option>B</option><option>C</option></select><input v-else v-model="condition.value" :type="['amountCents','inactiveDays'].includes(condition.field)?'number':'text'" step="any" required maxlength="100"/></label><button type="button" class="btn secondary" @click="editor.definition.conditions.splice(index,1)">移除</button></div><button v-if="editor.definition.conditions.length<10" type="button" class="btn secondary" @click="editor.definition.conditions.push({field:Object.keys(availableConditionFields)[0],operator:'EQ',value:''})">添加条件</button><p class="p6-muted">选择业务状态，金额以元填写。未配置条件表示对选定可见记录执行。</p><h3>执行动作</h3><section v-for="(action,index) in editor.definition.actions" :key="index" class="p7-action"><label>动作<select v-model="action.type" @change="action.value=action.type==='FILL_CUSTOMER_LEVEL'?'B':''"><option v-for="(name,id) in availableActions" :key="id" :value="id">{{name}}</option></select></label><label v-if="action.type==='FILL_CUSTOMER_LEVEL'">客户等级<select v-model="action.value"><option>A</option><option>B</option><option>C</option></select></label><label v-if="['CREATE_TASK','NOTIFY'].includes(action.type)">标题<input v-model="action.value" required maxlength="200"/></label><label v-if="['CREATE_TASK','NOTIFY','ASSIGN','SUBMIT_QUOTE'].includes(action.type)">{{action.type==='SUBMIT_QUOTE'?'审批人':'相关成员'}}<select v-model="action.memberId" :required="['ASSIGN','SUBMIT_QUOTE'].includes(action.type)"><option :value="null">执行成员本人</option><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label v-if="action.type==='CREATE_TASK'">待办几天后到期<input v-model.number="action.dueDays" type="number" min="0" max="365"/></label><button v-if="editor.definition.actions.length>1" type="button" class="btn secondary" @click="editor.definition.actions.splice(index,1)">移除动作</button></section><button v-if="editor.definition.actions.length<3" type="button" class="btn secondary" @click="editor.definition.actions.push({type:'NOTIFY',value:'',memberId:null,dueDays:0})">添加动作</button><p class="p6-muted">最多3个动作；任一步失败会回滚本次业务变更，保留失败记录。动作不能触发规则无限循环。</p></fieldset><button class="btn primary" :disabled="busy||readonly">保存为草稿</button></form>
<form v-else-if="dialog==='execute'" @submit.prevent="run(execute)"><p>{{editor.rule.name}} · {{names[editor.rule.entityType]}}</p><div class="p6-actions"><input v-model="targetQuery" aria-label="搜索执行记录" maxlength="100"/><button type="button" class="btn secondary" :disabled="busy" @click="targetPage=1;run(loadTargets)">搜索</button></div><label>选择业务记录<select v-model="editor.recordId" aria-label="选择业务记录" required><option value="" disabled>请选择当前可见记录</option><option v-for="r in targetRecords" :key="r.id" :value="r.id">{{r.recordTitle}}</option></select></label><div class="p6-pages"><span>第 {{targetPage}} 页 · 共 {{targetTotal}} 条</span><button type="button" class="btn secondary" :disabled="busy||targetPage<=1" @click="targetPage--;run(loadTargets)">上一页</button><button type="button" class="btn secondary" :disabled="busy||targetPage*20>=targetTotal" @click="targetPage++;run(loadTargets)">下一页</button></div><button class="btn primary" :disabled="busy||!editor.recordId">执行规则</button></form>
<template v-else-if="dialog==='record'"><h3>{{editor.recordTitle}}</h3><p class="p6-muted">{{names[type]}} · 版本 {{editor.version}} · {{editor.canWrite&&!readonly?'可维护获准扩展字段':'当前只读'}}</p><form @submit.prevent="run(saveFields)"><div class="p6-grid"><label v-for="field in fields" :key="field.id">{{field.label}}{{field.required?' *':''}}<textarea v-if="field.dataType==='TEXTAREA'" v-model="values[field.id]" :disabled="!field.canWrite||!editor.canWrite||readonly||busy" :required="field.required" maxlength="4000" rows="3"/><input v-else-if="field.dataType==='BOOLEAN'" v-model="values[field.id]" class="p7-checkbox" type="checkbox" :disabled="!field.canWrite||!editor.canWrite||readonly||busy"/><select v-else-if="['SELECT','MULTI_SELECT'].includes(field.dataType)" v-model="values[field.id]" :multiple="field.dataType==='MULTI_SELECT'" :required="field.required" :disabled="!field.canWrite||!editor.canWrite||readonly||busy"><option v-if="field.dataType==='SELECT'" value="">请选择</option><option v-for="option in field.options" :key="option">{{option}}</option></select><input v-else v-model="values[field.id]" :type="field.dataType==='DATE'?'date':field.dataType==='NUMBER'?'number':'text'" step="any" :required="field.required" :disabled="!field.canWrite||!editor.canWrite||readonly||busy" maxlength="4000"/></label></div><p v-if="!fields.length" class="p6-muted">尚无当前角色可见的扩展字段，企业管理员可在“行业配置”中添加。</p><button v-if="fields.some(f=>f.canWrite)&&editor.canWrite&&!readonly" class="btn primary" :disabled="busy">保存扩展资料</button></form><h3>业务附件</h3><form v-if="editor.canWrite&&!readonly" class="p6-toolbar" @submit.prevent="run(uploadFile)"><label>选择文件<input type="file" accept=".png,.jpg,.jpeg,.pdf,.txt,.csv" @change="upload=($event.target as HTMLInputElement).files?.[0]??null"/></label><button class="btn secondary" :disabled="busy||!upload||!data.storageConfigured">上传附件</button></form><p class="p6-muted">支持PNG、JPEG、PDF、TXT、CSV，单个文件最多5MB。已锁定或已入账记录保留只读历史。</p><div v-for="file in attachments" :key="file.id" class="p7-check"><div><strong>{{file.fileName}}</strong><small>{{(file.sizeBytes/1024).toFixed(1)}} KB · {{uiDate(file.createdAt)}}</small></div><button class="text-button" :disabled="busy" @click="run(()=>download(`/workspace/attachments/${file.id}/download`,file.fileName))">下载</button><button v-if="editor.canWrite&&!readonly" class="text-button" :disabled="busy" @click="run(()=>removeFile(file))">删除</button></div><p v-if="!attachments.length" class="p6-muted">暂无可见附件</p></template>
<form v-else-if="dialog==='draft'" @submit.prevent="run(saveDraft)"><div class="p6-grid"><label v-for="name in currentTemplate?.columns??[]" :key="name">{{name}}<select v-if="name==='类别'" v-model="editor[name]"><option>产品</option><option>服务</option></select><textarea v-else-if="/备注|说明|进展|成果|风险|计划/.test(name)" v-model="editor[name]" maxlength="4000" rows="3"/><input v-else v-model="editor[name]" :type="inputType(name)" :step="inputType(name)==='number'?'0.01':undefined" :min="inputType(name)==='number'?0:undefined" maxlength="200"/></label></div><p v-if="type==='TARGET'" class="p6-muted">目标对象填成员登录账号，或填写“部门：部门名称”；月份选择周期起始月，年度周期为12个月且需从1月开始。</p><p v-if="type==='ORDER'" class="p6-muted">填写当前可见的批准报价编号，生成订单草稿后仍需确认。</p><button class="btn primary" :disabled="busy||readonly">创建业务记录</button></form>
<form v-else-if="dialog==='policy'" @submit.prevent="run(savePolicy)"><label>业务对象<select v-model="editor.entityType"><option v-for="id in ['ORDER','INVOICE','EXPENSE','TARGET','COMMISSION','WEEKLY']" :key="id" :value="id">{{names[id]}}</option></select></label><label>角色<select v-model="editor.roleCode"><option v-for="(name,id) in roleNames" :key="id" :value="id">{{name}}</option></select></label><label class="p7-inline-label"><input v-model="editor.canRead" class="p7-checkbox" type="checkbox"/>允许读取</label><label class="p7-inline-label"><input v-model="editor.canWrite" class="p7-checkbox" type="checkbox" :disabled="editor.roleCode==='VIEWER'"/>允许写入</label><p class="p6-muted">同一成员拥有多个角色时合并授权；纯企业管理角色不会因此自动获得财务或销售数据。</p><button class="btn primary" :disabled="busy||readonly">保存权限</button></form>
<form v-else-if="dialog==='form'" @submit.prevent="run(createForm)"><label>表单名称<input v-model="editor.name" required maxlength="100"/></label><label>业务类型<select v-model="editor.entityType"><option value="LEAD">线索收集</option><option value="TICKET">服务需求</option></select></label><label>归属成员<select v-model="editor.ownerMemberId" required><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>有效天数<input v-model.number="editor.expiresDays" type="number" min="1" max="365" required/></label><button class="btn primary" :disabled="busy||readonly">创建外链</button></form>
<template v-else-if="dialog==='link'"><p class="p6-muted">链接仅本次显示，请复制后交给需要填写的人。可在表单列表随时撤销。</p><div class="p6-link">{{oneTime}}</div><a class="btn secondary" :href="oneTime" target="_blank" rel="noopener noreferrer">预览表单</a></template>
<template v-else-if="dialog==='run'"><p>执行状态：<strong>{{label(editor.status)}}</strong> · 尝试 {{editor.attempts}} 次</p><p v-if="editor.errorCode" class="p6-muted">请检查执行成员授权、规则版本与业务记录状态；修复后可在5次尝试上限内重试。</p><div v-for="attempt in editor.attemptHistory??[]" :key="attempt.attemptNo" class="p6-record"><strong>第 {{attempt.attemptNo}} 次 · {{label(attempt.outcome)}}</strong><small>{{uiDate(attempt.createdAt)}}</small></div></template>
<template v-else-if="dialog==='revisions'"><p>{{editor.rule.name}}</p><div v-for="revision in editor.items??[]" :key="revision.businessVersion" class="p6-record"><strong>发布版本 {{revision.businessVersion}}</strong><small>{{uiDate(revision.createdAt)}}</small></div><p v-if="!editor.items?.length" class="p6-muted">还没有发布版本</p></template>
</P6Dialog>
</section>
